# 1. Fix missing dossier_id from entry_id
for rec in records:
    if not rec.dossier_id and rec.entry_id:
        rec.write({'dossier_id': rec.entry_id.dossier_id.id})

# 2. Fix missing ste_id from dossier_id
for rec in records:
    if not rec.ste_id and rec.dossier_id:
        rec.write({'ste_id': rec.dossier_id.ste_id.id})
